<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {LayoutDashboard,Send,Users,Layers,Image,Server,ArrowUpCircle,ScrollText,Settings,Plus,RefreshCw,LogOut,ArrowUpRight,CheckCircle2,Clock3,ShieldCheck,Radio,UploadCloud,ChevronRight,Command} from 'lucide-vue-next';
import {ElMessage,ElMessageBox} from 'element-plus';import {api,setCsrf} from './api';
type Row=Record<string,any>;
const nav=[{id:'overview',label:'工作总览',icon:LayoutDashboard},{id:'jobs',label:'发布队列',icon:Send},{id:'accounts',label:'账号与授权',icon:Users},{id:'channels',label:'引擎与通道',icon:Layers},{id:'assets',label:'素材库',icon:Image},{id:'agents',label:'执行节点',icon:Server},{id:'updates',label:'版本与更新',icon:ArrowUpCircle},{id:'audit',label:'审计记录',icon:ScrollText},{id:'settings',label:'安全设置',icon:Settings}];
const labels:Row={bilibili:'B站',xiaohongshu:'小红书',tencent:'视频号',youtube:'YouTube',x:'X'};
const states:Row={queued:'排队中',preparing:'准备中',submitting:'提交中',submitted:'已提交',succeeded:'提交成功',needs_verify:'待核验',needs_action:'待处理',failed:'失败',cancelled:'已取消',retry_wait:'冷却等待',active:'有效',pending:'待授权',cooling:'已暂停',expired:'已过期',unverified:'未核验',healthy:'正常',degraded:'降级',broken:'熔断',available:'发现新版本',staged:'已隔离安装',canary:'灰度中',rolled_back:'已回滚'};
const user=ref<Row|null>(null),loading=ref(false),page=ref('overview'),overview=ref<Row>({jobs:{},platforms:[]});
const jobs=ref<Row[]>([]),accounts=ref<Row[]>([]),channels=ref<Row[]>([]),assets=ref<Row[]>([]),agents=ref<Row[]>([]),updates=ref<Row[]>([]),audits=ref<Row[]>([]);
const login=ref({username:'admin',password:'',totp:''}),dialog=ref(''),busy=ref(false),detail=ref<Row|null>(null),token=ref('');
const accountForm=ref({label:'',platform:'xiaohongshu',min_interval:60,mode:'direct',proxy:'',canary_allowed:false});
const jobForm=ref({account_id:'',title:'',description:'',kind:'video',assets:[] as string[],due:'',options:'{}',canary:false});
const credForm=ref({account_id:'',channel_id:'',value:''}),channelForm=ref({id:'',version:'',priority:50,enabled:false});
const recoveryCodes=ref<string[]>([]);
const agentLabel=ref(''),security=ref({current_password:'',password:''}),totpForm=ref({password:'',code:''}),totpSecret=ref<Row|null>(null);
let stream:EventSource|null=null;let timer:ReturnType<typeof setInterval>|null=null;
const title=computed(()=>nav.find(n=>n.id===page.value)?.label),total=computed(()=>Object.values(overview.value.jobs).reduce((a:number,b:any)=>a+Number(b),0));
const pending=computed(()=>['queued','preparing','submitting','retry_wait'].reduce((a,k)=>a+(overview.value.jobs[k]||0),0));
const attention=computed(()=>(overview.value.jobs.needs_verify||0)+(overview.value.jobs.needs_action||0));
const eligibleAssets=computed(()=>assets.value.filter(a=>a.kind===jobForm.value.kind));
const credentialChannels=computed(()=>channels.value.filter(c=>c.platform===accounts.value.find(a=>a.id===credForm.value.account_id)?.platform));
const activeAccount=computed(()=>accounts.value.find(a=>a.id===jobForm.value.account_id));
const fmt=(t:number)=>t?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(t*1000):'—';
const stateText=(s:string)=>states[s]||s;const good=(s:string)=>['healthy','active','succeeded'].includes(s);const bad=(s:string)=>['broken','failed','needs_verify','expired'].includes(s);
async function action(fn:()=>Promise<any>,message='已保存'){busy.value=true;try{await fn();ElMessage.success(message);dialog.value='';await refresh()}catch(e:any){ElMessage.error(e.message)}finally{busy.value=false}}
async function refresh(){if(!user.value)return;loading.value=true;try{const r=await Promise.all(['/overview','/jobs','/accounts','/channels','/assets','/agents','/updates','/audit'].map(p=>api(p)));[overview.value,jobs.value,accounts.value,channels.value,assets.value,agents.value,updates.value,audits.value]=r}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
function events(){stream?.close();stream=new EventSource('/api/events');stream.onmessage=()=>{if(!loading.value)void refresh()}}
async function signIn(){await action(async()=>{const r=await api('/login','POST',login.value);setCsrf(r.csrf);user.value=await api('/me');login.value.password='';events()},'登录成功')}
async function signOut(){await api('/logout','POST',{});stream?.close();user.value=null;setCsrf('')}
function newJob(){jobForm.value={account_id:'',title:'',description:'',kind:'video',assets:[],due:'',options:'{}',canary:false};dialog.value='job'}
async function saveJob(){await action(async()=>{const f=jobForm.value;await api('/jobs','POST',{idempotency_key:crypto.randomUUID(),account_id:f.account_id,title:f.title,description:f.description,kind:f.kind,assets:f.kind==='text'?[]:f.assets,due:f.due?Date.parse(f.due)/1000:null,options:JSON.parse(f.options),canary:f.canary})},'任务已加入队列')}
async function saveAccount(){await action(()=>api('/accounts','POST',{label:accountForm.value.label,platform:accountForm.value.platform,min_interval:accountForm.value.min_interval,canary_allowed:accountForm.value.canary_allowed,egress:accountForm.value.mode==='direct'?{mode:'direct'}:{mode:accountForm.value.mode,proxy:accountForm.value.proxy}}))}
async function saveCredential(){await action(()=>api(`/accounts/${credForm.value.account_id}/credentials`,'POST',{channel_id:credForm.value.channel_id,value:JSON.parse(credForm.value.value)}));credForm.value.value=''}
async function upload(event:Event){const input=event.target as HTMLInputElement;for(const file of Array.from(input.files||[])){const f=new FormData();f.append('file',file);await action(()=>api('/assets','POST',f),'素材已上传')}input.value=''}
async function openDetail(id:string){detail.value=await api('/jobs/'+id);dialog.value='detail'}
async function jobAction(job:Row,kind:string){try{let remote_id:string|undefined;if(kind==='confirm_published'){const p=await ElMessageBox.prompt('输入在平台核验过的实际作品 ID','确认已发布',{inputValidator:v=>!!v||'作品 ID 为必填'});remote_id=p.value}else await ElMessageBox.confirm(kind==='confirm_not_published'?'请确认已检查平台作品列表，确实未发布。确认后会允许重新提交。':'确认执行此操作？','任务操作',{type:'warning'});await action(()=>api('/jobs/'+job.id+'/action','POST',{action:kind,remote_id}));if(detail.value)detail.value=await api('/jobs/'+job.id)}catch(e:any){if(e?.message)ElMessage.error(e.message)}}
function editChannel(c:Row){channelForm.value={id:c.id,version:c.version,priority:c.priority,enabled:c.enabled};dialog.value='channel'}
async function attest(c:Row){try{const p=await ElMessageBox.prompt('仅填写同版本、同通道真实发布并核验的作品 ID。安装和模拟结果不算实测。','记录真实核验');await action(()=>api('/channels/'+c.id+'/verify','POST',{action:'attest_live',remote_id:p.value}))}catch(e:any){if(e?.message)ElMessage.error(e.message)}}
async function registerAgent(){busy.value=true;try{const r=await api('/agents','POST',{label:agentLabel.value});token.value=r.token;await refresh()}catch(e:any){ElMessage.error(e.message)}finally{busy.value=false}}
async function checkUpdates(){await action(()=>api('/updates/check','POST',{}),'上游检查完成')}
async function updateAction(row:Row,kind:string){await action(()=>api('/updates/'+row.id+'/action','POST',{action:kind}))}
async function changePassword(){await action(async()=>{await api('/password','POST',security.value);stream?.close();user.value=null;security.value={current_password:'',password:''}},'密码已修改')}
async function confirmTotp(){busy.value=true;try{const r=await api('/totp/confirm','POST',totpForm.value);user.value!.totp_enabled=true;totpSecret.value=null;recoveryCodes.value=r.recovery_codes;dialog.value='recovery'}catch(e:any){ElMessage.error(e.message)}finally{busy.value=false}}
async function enableTotp(){try{totpSecret.value=await api('/totp/setup','POST',{password:totpForm.value.password,code:''})}catch(e:any){ElMessage.error(e.message)}}
onMounted(async()=>{try{user.value=await api('/me');setCsrf(user.value!.csrf);await refresh();events()}catch{}timer=setInterval(()=>{if(user.value&&!loading.value)void refresh()},30000)});
onUnmounted(()=>{stream?.close();if(timer)clearInterval(timer)});
</script>
<template>
<div v-if="!user" class="login-shell"><div class="login-art"><div class="brand"><Command :size="30"/><span>OmniDispatch</span></div><div><span class="eyebrow">ONE WORKSPACE. EVERY CHANNEL.</span><h1>内容抵达每一站，<br>每一步都有记录。</h1><p>把账号、引擎、发布与更新放进同一条可靠流程。</p><div class="platform-pills"><span v-for="v in labels" :key="v">{{v}}</span></div></div><small>可追踪 · 保留发布主体 · 结果未知时暂停重发</small></div><div class="login-panel"><div class="login-card"><span class="eyebrow">YOUR PUBLISHING WORKSPACE</span><h2>登录发布中枢</h2><p>使用本机初始化的管理员账户。</p><el-form @submit.prevent="signIn" label-position="top"><el-form-item label="用户名"><el-input v-model="login.username" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="login.password" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="动态验证码（启用后填写）"><el-input v-model="login.totp" inputmode="numeric" autocomplete="one-time-code"/></el-form-item><el-button class="wide" type="primary" native-type="submit" :loading="busy">进入工作台 <ArrowUpRight :size="16"/></el-button></el-form><div class="login-hint"><ShieldCheck :size="17"/> 初始凭据保存在本机私密文件；首次登录后请修改。</div></div></div></div>
<div v-else class="shell"><aside class="sidebar"><div class="brand"><Command :size="25"/><span>OmniDispatch<small>PUBLISHING WORKSPACE</small></span></div><div class="workspace"><span class="avatar">O</span><div>我的发布中枢<small>独立工作空间</small></div><ChevronRight :size="14"/></div><span class="nav-label">工作空间</span><nav><button v-for="item in nav" :key="item.id" :aria-label="item.label" :class="{active:page===item.id}" @click="page=item.id"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><b v-if="item.id==='jobs'&&attention">{{attention}}</b></button></nav><div class="sidebar-bottom"><div class="node-dot"><i/> {{overview.agents_online||0}} 个节点在线</div><button @click="signOut"><LogOut :size="16"/> 退出登录</button></div></aside>
<main><header><div class="breadcrumbs">工作空间 <ChevronRight :size="14"/> <strong>{{title}}</strong></div><div class="header-right"><span class="time-label">北京时间</span><span class="admin-avatar">A</span><span>{{user.username}}</span></div></header><section class="content"><div class="page-heading"><div><span class="eyebrow">{{page==='overview'?'WORKSPACE OVERVIEW':'PUBLISHING OPERATIONS'}}</span><h1>{{title}}<span v-if="page==='overview'" class="live-label"><i/> 实时账本</span></h1><p>{{page==='overview'?'从内容准备到平台提交，让每次发布都清晰可见。':page==='channels'?'按真实能力选择通道，候选与实测状态分开展示。':page==='updates'?'先发现、验证与灰度，再切换。正在执行的任务保持原版本。':'集中管理，所有操作保留审计记录。'}}</p></div><div class="heading-actions"><el-button :loading="loading" @click="refresh"><RefreshCw :size="15"/>刷新</el-button><el-button v-if="['overview','jobs'].includes(page)" type="primary" @click="newJob"><Plus :size="17"/>新建发布</el-button><el-button v-if="page==='accounts'" type="primary" @click="dialog='account'"><Plus :size="17"/>添加账号</el-button><el-button v-if="page==='agents'" type="primary" @click="token='';dialog='agent'"><Plus :size="17"/>添加节点</el-button><el-button v-if="page==='updates'" type="primary" :loading="busy" @click="checkUpdates"><RefreshCw :size="16"/>检查更新</el-button></div></div>
<template v-if="page==='overview'"><div class="stats-grid"><article class="stat"><span>累计发布任务 <Send :size="17"/></span><strong>{{total}}</strong><small>全部发布意图，重复请求合并</small></article><article class="stat"><span>平台接受提交 <CheckCircle2 :size="17"/></span><strong>{{overview.jobs.succeeded||0}}<em>条</em></strong><small>平台审核与公开状态以平台为准</small></article><article class="stat"><span>正在流转 <Clock3 :size="17"/></span><strong>{{pending}}<em>条</em></strong><small>排队、准备、提交或冷却中</small></article><article class="stat attention"><span>需要关注 <Radio :size="17"/></span><strong>{{attention}}<em>条</em></strong><small>授权待处理或提交结果待核验</small></article></div><div class="panel"><div class="panel-heading"><div><h3>五平台通道视图</h3><p>只有真实核验并启用的通道计入可用数量。</p></div><button class="text-button" @click="page='channels'">管理通道 <ArrowUpRight :size="15"/></button></div><div class="platform-grid"><article v-for="p in overview.platforms" :key="p.id" class="platform-card"><div class="platform-icon" :data-platform="p.id">{{p.label[0]}}</div><h3>{{p.label}}</h3><span class="badge" :class="p.verified?'good':'neutral'">{{p.verified?'已启用':'待配置与核验'}}</span><div class="channel-count"><strong>{{p.verified}}</strong><span>/ {{p.candidates}} 候选通道</span></div><small>{{p.fault_domains}} 个已核验故障域</small></article></div></div><div class="overview-lower"><div class="panel"><div class="panel-heading"><h3>最近任务</h3><button class="text-button" @click="page='jobs'">查看全部 <ArrowUpRight :size="15"/></button></div><div v-if="!jobs.length" class="empty"><Send :size="32"/><h3>准备好你的第一条内容</h3><p>添加账号并完成通道授权后，即可创建发布任务。</p><el-button @click="newJob">创建发布任务</el-button></div><button v-for="j in jobs.slice(0,5)" :key="j.id" class="job-preview" @click="openDetail(j.id)"><div><strong>{{j.payload.title}}</strong><small>{{labels[j.platform]}} · {{fmt(j.created)}}</small></div><span class="badge" :class="good(j.state)?'good':bad(j.state)?'bad':'neutral'">{{stateText(j.state)}}</span></button></div><div class="panel guide"><ShieldCheck :size="26"/><h3>可靠发布的三个边界</h3><div><b>01</b><p>发布账号固定，授权失效时暂停。</p></div><div><b>02</b><p>提交结果未知时先核验，再决定重发。</p></div><div><b>03</b><p>新版本先灰度，旧任务继续使用旧版本。</p></div></div></div></template>
<div v-if="page==='jobs'" class="panel"><el-table :data="jobs" empty-text="还没有发布任务，点击右上角创建。" @row-click="(r:Row)=>openDetail(r.id)" class="clickable"><el-table-column label="内容" min-width="220"><template #default="{row}"><strong>{{row.payload.title}}</strong><small class="cell-sub">{{row.reason||'等待任务执行'}}</small></template></el-table-column><el-table-column label="平台" width="110"><template #default="{row}">{{labels[row.platform]}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><span class="badge" :class="good(row.state)?'good':bad(row.state)?'bad':'neutral'">{{stateText(row.state)}}</span></template></el-table-column><el-table-column label="计划时间" width="145"><template #default="{row}">{{fmt(row.due)}}</template></el-table-column><el-table-column prop="engine_version" label="固定版本" width="130"/></el-table></div>
<div v-if="page==='accounts'" class="account-grid"><article v-for="a in accounts" :key="a.id" class="panel account-card"><div class="panel-heading"><div class="account-title"><span class="platform-icon" :data-platform="a.platform">{{labels[a.platform][0]}}</span><div><h3>{{a.label}}</h3><small>{{labels[a.platform]}}</small></div></div><span class="badge" :class="good(a.state)?'good':'neutral'">{{stateText(a.state)}}</span></div><div class="account-meta"><span>出口模式 <strong>{{a.egress.mode}}</strong></span><span>发布间隔 <strong>{{a.min_interval}} 秒</strong></span><span>通道授权 <strong>{{a.credentials.length}} 份</strong></span></div><div v-for="c in a.credentials" :key="c.id" class="credential-row"><span>{{c.channel_id}}</span><span class="badge" :class="good(c.state)?'good':'bad'">{{stateText(c.state)}}</span></div><div class="card-actions"><el-button @click="credForm={account_id:a.id,channel_id:'',value:''};dialog='credential'">管理授权</el-button><el-button text @click="action(()=>api('/accounts/'+a.id+'/state','POST',{action:a.state==='active'?'cooling':'active'}))">{{a.state==='active'?'暂停账号':'恢复账号'}}</el-button></div></article><div v-if="!accounts.length" class="panel empty wide-grid"><Users :size="34"/><h3>添加你的第一个发布账号</h3><p>同一账号可以分别保存多条通道授权，发布时保持账号不变。</p><el-button type="primary" @click="dialog='account'">添加账号</el-button></div></div>
<div v-if="page==='channels'" class="panel"><div class="notice"><ShieldCheck :size="18"/> 安装检查不等于真实发布验收。候选通道默认关闭，避免误报可用。</div><el-table :data="channels" row-key="id"><el-table-column label="通道" min-width="210"><template #default="{row}"><strong>{{row.engine}}</strong><small class="cell-sub">{{row.id}}</small></template></el-table-column><el-table-column label="平台" width="100"><template #default="{row}">{{labels[row.platform]}}</template></el-table-column><el-table-column label="版本" prop="version" min-width="125"/><el-table-column label="健康" width="100"><template #default="{row}"><span class="badge" :class="good(row.health)?'good':'neutral'">{{stateText(row.health)}}</span></template></el-table-column><el-table-column label="已启用" width="80"><template #default="{row}">{{row.enabled?'是':'否'}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button text @click="editChannel(row)">配置</el-button><el-button text @click="attest(row)">实测核验</el-button></template></el-table-column></el-table></div>
<div v-if="page==='assets'" class="panel"><label class="upload-area"><UploadCloud :size="36"/><strong>选择图片或视频上传</strong><span>支持 MP4、MOV、WebM、MKV、JPG、PNG、WebP · 单文件最大 2 GiB</span><input type="file" multiple accept=".mp4,.mov,.webm,.mkv,.jpg,.jpeg,.png,.webp" @change="upload"/></label><el-table :data="assets" empty-text="素材库为空"><el-table-column prop="name" label="文件名"/><el-table-column label="类型" width="120"><template #default="{row}">{{row.kind==='video'?'视频':'图片'}}</template></el-table-column><el-table-column label="大小" width="140"><template #default="{row}">{{(row.size/1024/1024).toFixed(2)}} MB</template></el-table-column><el-table-column label="上传时间" width="150"><template #default="{row}">{{fmt(row.created)}}</template></el-table-column></el-table></div>
<div v-if="page==='agents'" class="account-grid"><article v-for="a in agents" :key="a.id" class="panel account-card"><div class="panel-heading"><h3><Server :size="19"/> {{a.label}}</h3><span class="badge" :class="a.enabled&&a.last_seen>Date.now()/1000-90?'good':'neutral'">{{!a.enabled?'已撤销':a.last_seen>Date.now()/1000-90?'在线':'离线'}}</span></div><p>最后心跳：{{fmt(a.last_seen)}}</p><p>上报通道：{{Object.keys(a.capabilities.channels||{}).length}}</p><el-button type="danger" plain :disabled="!a.enabled" @click="action(()=>api('/agents/'+a.id+'/revoke','POST',{}),'节点已撤销')">撤销节点</el-button></article><div v-if="!agents.length" class="panel empty wide-grid"><Server :size="32"/><h3>等待执行节点</h3><p>节点主动连接中枢，无需对外开放引擎端口。</p></div></div>
<div v-if="page==='updates'" class="panel"><div class="notice"><ShieldCheck :size="18"/> 每日自动检查。升级包需受信签名；灰度至少 24 小时并有真实成功样本，才允许提升。</div><el-table :data="updates" empty-text="尚无更新记录，可手动检查上游"><el-table-column prop="engine" label="引擎" min-width="140"/><el-table-column prop="version" label="候选版本" min-width="140"/><el-table-column label="阶段" width="130"><template #default="{row}"><span class="badge neutral">{{stateText(row.state)}}</span></template></el-table-column><el-table-column label="上游来源" min-width="150"><template #default="{row}"><a :href="row.source" target="_blank" rel="noopener noreferrer">查看发行说明 ↗</a></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button v-if="row.state==='staged'" text @click="updateAction(row,'canary')">启动灰度</el-button><el-button v-if="row.state==='canary'" text @click="updateAction(row,'promote')">提升版本</el-button><el-button v-if="['active','canary'].includes(row.state)" text @click="updateAction(row,'rollback')">回滚</el-button><span v-if="row.state==='available'" class="muted">等待签名安装包</span></template></el-table-column></el-table></div>
<div v-if="page==='audit'" class="panel"><el-table :data="audits" empty-text="暂无审计事件"><el-table-column label="时间" width="150"><template #default="{row}">{{fmt(row.created)}}</template></el-table-column><el-table-column prop="event" label="事件" min-width="180"/><el-table-column prop="subject" label="对象" min-width="230"/><el-table-column label="详情" min-width="220"><template #default="{row}"><code>{{JSON.stringify(row.detail)}}</code></template></el-table-column></el-table></div>
<div v-if="page==='settings'" class="settings-grid"><div class="panel"><h3>修改管理员密码</h3><p>修改后所有登录会话失效，请重新登录。</p><el-form label-position="top" @submit.prevent="changePassword"><el-form-item label="当前密码"><el-input v-model="security.current_password" type="password" show-password/></el-form-item><el-form-item label="新密码（至少 12 位）"><el-input v-model="security.password" type="password" show-password/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">更新密码</el-button></el-form></div><div class="panel"><h3>双因素认证</h3><p>{{user.totp_enabled?'已启用 TOTP 动态验证码。':'添加动态验证码，保护管理员登录。'}}</p><el-form v-if="!user.totp_enabled" label-position="top"><el-form-item label="验证当前密码"><el-input v-model="totpForm.password" type="password"/></el-form-item><el-button v-if="!totpSecret" @click="enableTotp">生成验证器密钥</el-button><template v-else><p>在验证器中手动添加以下密钥：</p><code class="secret">{{totpSecret.secret}}</code><el-form-item label="验证器当前验证码"><el-input v-model="totpForm.code"/></el-form-item><el-button type="primary" @click="confirmTotp">确认启用</el-button></template></el-form></div></div>
<footer>OmniDispatch <span>·</span> 发布可追踪，更新有边界 <span class="footer-right">v0.1.0</span></footer></section></main>
<el-dialog :model-value="!!dialog" @close="dialog=''" :title="({job:'新建发布任务',account:'添加发布账号',credential:'保存通道授权',channel:'配置引擎通道',agent:'添加执行节点',detail:'发布任务详情',recovery:'保存双因素恢复码'} as Row)[dialog]" width="min(640px,94vw)">
<el-form v-if="dialog==='job'" label-position="top"><div class="form-grid"><el-form-item label="发布账号"><el-select v-model="jobForm.account_id" placeholder="选择账号"><el-option v-for="a in accounts" :key="a.id" :label="`${a.label} · ${labels[a.platform]}`" :value="a.id"/></el-select></el-form-item><el-form-item label="内容类型"><el-select v-model="jobForm.kind" @change="jobForm.assets=[]"><el-option label="视频" value="video"/><el-option label="图文" value="images"/><el-option label="纯文本（X API）" value="text"/></el-select></el-form-item></div><el-form-item label="标题"><el-input v-model="jobForm.title" maxlength="300" show-word-limit/></el-form-item><el-form-item label="正文"><el-input v-model="jobForm.description" type="textarea" :rows="4"/></el-form-item><el-form-item v-if="jobForm.kind!=='text'" label="选择素材（先在素材库上传）"><el-select v-model="jobForm.assets" multiple><el-option v-for="a in eligibleAssets" :key="a.id" :label="a.name" :value="a.id"/></el-select></el-form-item><el-form-item label="计划执行时间（留空立即排队；按当前浏览器时区）"><input class="date-input" v-model="jobForm.due" type="datetime-local"/></el-form-item><el-form-item label="平台参数 JSON（例如 B站分区、YouTube 可见性）"><el-input v-model="jobForm.options" type="textarea" :rows="3"/></el-form-item><el-form-item label="灰度测试任务（仅可用于已允许测试的账号）"><el-switch v-model="jobForm.canary"/></el-form-item><div class="notice small">发布主体固定为 {{activeAccount?.label||'所选账号'}}。未具备授权和可用通道时，任务会等待。</div><el-button type="primary" :loading="busy" @click="saveJob">加入发布队列</el-button></el-form>
<el-form v-if="dialog==='account'" label-position="top"><el-form-item label="账号名称"><el-input v-model="accountForm.label"/></el-form-item><el-form-item label="平台"><el-select v-model="accountForm.platform"><el-option v-for="(label,id) in labels" :key="id" :label="label" :value="id"/></el-select></el-form-item><el-form-item label="最小发布间隔（秒）"><el-input-number v-model="accountForm.min_interval" :min="30" :max="86400"/></el-form-item><el-form-item label="允许此账号进行灰度测试"><el-switch v-model="accountForm.canary_allowed"/></el-form-item><el-form-item label="出口模式"><el-select v-model="accountForm.mode"><el-option label="直连" value="direct"/><el-option label="可信静态代理" value="trusted-static"/><el-option label="Resin 粘性代理" value="resin"/></el-select></el-form-item><el-form-item v-if="accountForm.mode!=='direct'" label="明确代理地址（含绑定标识）"><el-input v-model="accountForm.proxy" type="password" show-password placeholder="http://platform.account:token@host:port"/></el-form-item><p class="muted">代理能力尚未验证的通道会停止执行，不会回退直连。</p><el-button type="primary" :loading="busy" @click="saveAccount">保存账号</el-button></el-form>
<el-form v-if="dialog==='credential'" label-position="top"><el-form-item label="通道"><el-select v-model="credForm.channel_id"><el-option v-for="c in credentialChannels" :key="c.id" :label="c.id" :value="c.id"/></el-select></el-form-item><el-form-item label="独立通道凭证 JSON"><el-input v-model="credForm.value" type="textarea" :rows="8" placeholder='X API: {"access_token":"用户 OAuth token"}；YouTube: {"client_secrets":{...},"token":{...}}'/></el-form-item><p class="muted">凭证加密保存，界面不会回显。不同通道的登录态分别管理。</p><el-button type="primary" :loading="busy" @click="saveCredential">加密保存</el-button></el-form>
<el-form v-if="dialog==='channel'" label-position="top"><el-form-item label="通道"><el-input :model-value="channelForm.id" disabled/></el-form-item><el-form-item label="固定引擎版本"><el-input v-model="channelForm.version"/></el-form-item><el-form-item label="优先级"><el-input-number v-model="channelForm.priority" :min="0" :max="100"/></el-form-item><el-form-item label="启用路由（需先记录真实核验）"><el-switch v-model="channelForm.enabled"/></el-form-item><el-button type="primary" :loading="busy" @click="action(()=>api('/channels/'+channelForm.id,'POST',{version:channelForm.version,priority:channelForm.priority,enabled:channelForm.enabled}))">保存配置</el-button></el-form>
<div v-if="dialog==='agent'"><el-form v-if="!token" label-position="top"><el-form-item label="节点名称"><el-input v-model="agentLabel"/></el-form-item><el-button type="primary" :loading="busy" @click="registerAgent">创建节点授权</el-button></el-form><template v-else><div class="notice">此令牌只展示一次。将其保存到节点私密 agent.json，勿发送到公开仓库。</div><el-input :model-value="token" type="textarea" :rows="4" readonly/><p>启动命令：<code>omnidispatch agent --config agent.json</code></p></template></div>
<div v-if="dialog==='recovery'"><p>恢复码仅展示这一次。每个码只能使用一次，可在登录验证码框中输入。请离线保存。</p><code class="secret" v-for="code in recoveryCodes" :key="code">{{code}}</code></div><div v-if="dialog==='detail'&&detail"><h3>{{detail.payload.title}}</h3><div class="detail-meta"><span class="badge neutral">{{stateText(detail.state)}}</span><span>{{labels[detail.platform]}}</span><span>{{fmt(detail.created)}}</span></div><p>{{detail.reason}}</p><p v-if="detail.remote_id">平台作品 ID：<code>{{detail.remote_id}}</code></p><div class="notice small">{{detail.state==='needs_verify'?'提交结果未知：先查平台作品列表，核验前不会重新提交。':'上传提交成功与平台审核通过、公开可见是不同阶段。'}}</div><h4>通道尝试记录</h4><el-table :data="detail.attempts" empty-text="尚未领取执行"><el-table-column prop="generation" label="代次" width="65"/><el-table-column prop="channel_id" label="通道"/><el-table-column prop="version" label="版本"/><el-table-column label="状态"><template #default="{row}">{{stateText(row.state)}}</template></el-table-column></el-table><div class="card-actions"><template v-if="detail.state==='needs_verify'"><el-button type="primary" @click="jobAction(detail,'confirm_published')">确认已发布</el-button><el-button @click="jobAction(detail,'confirm_not_published')">确认未发布并重试</el-button></template><el-button v-if="['needs_action','failed','retry_wait'].includes(detail.state)" @click="jobAction(detail,'retry')">恢复排队</el-button><el-button v-if="['queued','needs_action','retry_wait'].includes(detail.state)" @click="jobAction(detail,'cancel')">取消任务</el-button></div></div>
</el-dialog></div>
</template>
